WITH scored AS (SELECT id, txn_type, merchant, FIRST_VALUE(amount, TRUE) OVER (PARTITION BY merchant ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) first_known_amount, SUM(amount) OVER (ORDER BY amount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) cumulative_amount, COUNT(amount) OVER (PARTITION BY txn_type) txn_type_count_amount, LEAD(amount, 1) OVER (PARTITION BY account_id ORDER BY txn_time, id) next_amount FROM transactions), enriched AS (SELECT id, txn_type, cumulative_amount, txn_type_count_amount, ROUND(txn_type_count_amount / SUM(txn_type_count_amount) OVER (PARTITION BY merchant), 4) txn_type_count_amount_share, ROUND(cumulative_amount / SUM(cumulative_amount) OVER (PARTITION BY merchant), 4) cumulative_amount_share FROM scored WHERE merchant != 'Shell'), deduped AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY txn_type ORDER BY cumulative_amount_share DESC NULLS FIRST, id) AS rank_in_group FROM enriched) ranked WHERE rank_in_group = 1), ranked AS (SELECT * FROM deduped QUALIFY ROW_NUMBER() OVER (PARTITION BY txn_type ORDER BY txn_type_count_amount NULLS FIRST, id) = 1), valid AS (SELECT id, txn_type, cumulative_amount, cumulative_amount_share, rank_in_group, ROUND(txn_type_count_amount_share / cumulative_amount, 2) txn_type_count_amount_share_per_cumulative_amount, rank_in_group / NULLIF(txn_type_count_amount_share, 0) rank_in_group_per_txn_type_count_amount_share FROM ranked WHERE rank_in_group > 1), scored_transactions AS (SELECT id, txn_type, txn_type_count_amount_share_per_cumulative_amount, rank_in_group_per_txn_type_count_amount_share, RANK() OVER (PARTITION BY txn_type ORDER BY rank_in_group_per_txn_type_count_amount_share DESC) rank_in_group_per_txn_type_count_amount_share_rank, AVG(cumulative_amount_share) OVER w_running cumulative_amount_share_avg_5_prior, LEAD(rank_in_group_per_txn_type_count_amount_share, 1) OVER (ORDER BY rank_in_group, id) next_rank_in_group_per_txn_type_count_amount_share FROM valid WINDOW w_running AS (ORDER BY txn_type_count_amount_share_per_cumulative_amount, id ROWS BETWEEN 5 PRECEDING AND 1 PRECEDING)) SELECT txn_type, COUNT(*) FILTER (WHERE txn_type = 'CREDIT') AS credit_rows, COUNT(CASE WHEN txn_type = 'FEE' THEN 1 END) AS fee_count, PERCENTILE_APPROX(rank_in_group_per_txn_type_count_amount_share, ARRAY(0.25, 0.5, 0.75)) AS rank_in_group_per_txn_type_count_amount_share_quartiles, SIZE(COLLECT_SET(txn_type)) AS num_txn_types FROM scored_transactions GROUP BY txn_type ORDER BY num_txn_types DESC NULLS FIRST;
